package io.github.rivomesh.transport.artemis;

import org.apache.activemq.artemis.api.core.*;
import org.apache.activemq.artemis.api.core.client.*;
import org.apache.activemq.artemis.core.remoting.impl.netty.NettyConnectorFactory;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Actual old-client/current-broker interoperability; no production availability claim from compilation. */
public final class ArtemisTransportAcceptance {
    static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    static ArtemisTransport.Publication publication(String id){ArtemisTransport.Publication p=new ArtemisTransport.Publication();p.id=id;p.channel="sales.items";p.key="key-"+id;p.body=("{\"id\":\""+id+"\",\"exact\":\"18446744073709551615\",\"text\":\"中文\"}").getBytes(StandardCharsets.UTF_8);return p;}
    static Set<String> queues(ArtemisTransport inspector)throws Exception{Set<String> result=new TreeSet<>();for(Object name:(Object[])inspector.attribute("broker","queueNames"))if(String.valueOf(name).startsWith("rivomesh."))result.add(String.valueOf(name));return result;}
    static List<String> read(ArtemisTransport.Settings settings,String queue,boolean acknowledge)throws Exception{
        Map<String,Object> parameters=new HashMap<>();parameters.put("host","artemis");parameters.put("port",61616);parameters.put("useEpoll",false);parameters.put("useKQueue",false);parameters.put("nioRemotingThreads",1);List<String> ids=new ArrayList<>();
        try(ServerLocator locator=ActiveMQClient.createServerLocatorWithoutHA(new TransportConfiguration(NettyConnectorFactory.class.getName(),parameters))){locator.setUseGlobalPools(false).setThreadPoolMaxSize(2).setScheduledThreadPoolMaxSize(1).setBlockOnAcknowledge(true).setConsumerWindowSize(0);try(ClientSessionFactory factory=locator.createSessionFactory();ClientSession session=factory.createSession(settings.username,settings.password,false,true,true,false,0)){session.start();try(ClientConsumer consumer=session.createConsumer(queue,!acknowledge)){for(int i=0;i<10;i++){ClientMessage message=consumer.receive(i==0?3000:200);if(message==null)break;if(message.getStringProperty("rivomesh_publication_manifest")==null){String id=message.getStringProperty("rivomesh_event_id");byte[] bytes=new byte[message.getBodyBuffer().readableBytes()];message.getBodyBuffer().readBytes(bytes);require(Arrays.equals(publication(id).body,bytes),"Body changed");require("sales.items".equals(message.getStringProperty("rivomesh_channel")),"Channel changed");require(("key-"+id).equals(message.getStringProperty("rivomesh_key")),"Key changed");ids.add(id);}if(acknowledge)message.acknowledge();}}}}
        return ids;
    }
    public static void main(String[] args)throws Exception{
        Class.forName("io.github.rivomesh.artemis.internal.netty.channel.Channel");Class.forName("io.github.rivomesh.artemis.internal.json.Json");
        ArtemisTransport.Settings settings=new ArtemisTransport.Settings();settings.url="artemis://artemis:61616";settings.username="rivomesh";settings.password="Artemis@Test123";settings.queuePrefix="rivomesh";settings.brokerName="rivomesh-artemis";settings.requestTimeoutMillis=5000;
        String binding="rivomesh:"+String.format("%064x",new java.math.BigInteger(UUID.randomUUID().toString().replace("-",""),16)),queue=ArtemisTransport.physicalQueue(settings.queuePrefix,binding),identity,firstProgress,laterProgress;
        try(ArtemisTransport inspector=new ArtemisTransport(settings,null)){Set<String> before=queues(inspector);ArtemisTransport.check(settings);require(before.equals(queues(inspector)),"Check created a business queue");}
        try(ArtemisTransport transport=new ArtemisTransport(settings,binding)){transport.prepare(true);identity=transport.identity();require(identity!=null,"Resource identity missing");transport.publish(Collections.singletonList(publication("first")));firstProgress=transport.confirmedProgress();require(firstProgress!=null,"Native progress missing");require(read(settings,queue,false).equals(Collections.singletonList("first")),"Confirmed event missing");require(read(settings,queue,true).contains("first"),"Normal consumer could not read");require(read(settings,queue,false).contains("first"),"Consumer ACK removed retained history");}
        Path markers=Paths.get(System.getenv("RIVOMESH_ARTEMIS_RESTART_DIR"));Files.write(markers.resolve("restart.request"),new byte[]{1});long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(180);while(!Files.exists(markers.resolve("restart.done"))&&System.nanoTime()<deadline)Thread.sleep(100);require(Files.exists(markers.resolve("restart.done")),"Broker restart did not execute");
        try(ArtemisTransport restored=new ArtemisTransport(settings,binding)){restored.resumeProgress(firstProgress);restored.prepare(false);require(identity.equals(restored.identity()),"Node/queue identity changed across restart");restored.publish(Collections.singletonList(publication("second")));laterProgress=restored.confirmedProgress();require(!firstProgress.equals(laterProgress),"Native receipt did not advance");require(read(settings,queue,false).containsAll(Arrays.asList("first","second")),"Restart lost confirmed history");}
        try(ArtemisTransport invalid=new ArtemisTransport(settings,binding)){try{invalid.resumeProgress("bad");throw new AssertionError("Malformed receipt accepted");}catch(ArtemisTransport.Failure failure){require("ARTEMIS_PROGRESS_INVALID".equals(failure.code),"Wrong malformed receipt error");}}
        String altered=laterProgress.substring(0,laterProgress.length()-1)+(laterProgress.endsWith("0")?"1":"0");
        try(ArtemisTransport changed=new ArtemisTransport(settings,binding)){changed.resumeProgress(altered);try{changed.prepare(false);throw new AssertionError("Altered digest accepted");}catch(ArtemisTransport.Failure failure){require(failure.code.startsWith("ARTEMIS_CONFIRMED_HISTORY_"),"Wrong digest error: "+failure.code);}}
        Files.write(markers.resolve("restore.request"),new byte[]{1});deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(180);while(!Files.exists(markers.resolve("restore.done"))&&System.nanoTime()<deadline)Thread.sleep(100);require(Files.exists(markers.resolve("restore.done")),"Old-volume restore did not execute");
        require(read(settings,queue,false).equals(Collections.singletonList("first")),"Restore fixture is not an older nonempty publication");
        try(ArtemisTransport rollback=new ArtemisTransport(settings,binding)){rollback.resumeProgress(laterProgress);try{rollback.prepare(true);throw new AssertionError("Old same-ID backup accepted with later receipt");}catch(ArtemisTransport.Failure failure){require("ARTEMIS_CONFIRMED_HISTORY_MISSING_REBUILD_REQUIRED".equals(failure.code),"Wrong rollback error: "+failure.code);}}
        try(ArtemisTransport original=new ArtemisTransport(settings,binding)){original.resumeProgress(firstProgress);original.prepare(false);require(identity.equals(original.identity()),"Rollback fixture changed node/queue identity");original.operation("broker","updateQueue",new QueueConfiguration(queue).setNonDestructive(false).toJSON());}
        try(ArtemisTransport unsafe=new ArtemisTransport(settings,binding)){try{unsafe.prepare(false);throw new AssertionError("Destructive queue accepted");}catch(ArtemisTransport.Failure failure){require("ARTEMIS_QUEUE_CONFIGURATION_REQUIRES_PLAN".equals(failure.code),"Wrong shape error: "+failure.code);}}
        try(ArtemisTransport inspector=new ArtemisTransport(settings,null)){inspector.operation("broker","destroyQueue",queue);}
        try(ArtemisTransport lost=new ArtemisTransport(settings,binding)){try{lost.prepare(false);throw new AssertionError("Missing initialized queue recreated");}catch(ArtemisTransport.Failure failure){require("MESSAGE_DESTINATION_MISSING_REBUILD_REQUIRED".equals(failure.code),"Wrong missing-resource error: "+failure.code);}}
        try(ArtemisTransport inspector=new ArtemisTransport(settings,null)){inspector.operation("broker","createQueue",new QueueConfiguration(queue).setAddress(queue).setRoutingType(RoutingType.ANYCAST).setDurable(true).setTemporary(false).setNonDestructive(true).setAutoDelete(false).setPurgeOnNoConsumers(false).setRingSize(-1L).setAutoCreateAddress(true).toJSON());}
        try(ArtemisTransport empty=new ArtemisTransport(settings,binding)){empty.resumeProgress(firstProgress);try{empty.prepare(true);throw new AssertionError("Empty replacement repaired despite saved receipt");}catch(ArtemisTransport.Failure failure){require("ARTEMIS_PUBLICATION_MANIFEST_MISSING".equals(failure.code),"Wrong empty-replacement error: "+failure.code);}}
        try(ArtemisTransport inspector=new ArtemisTransport(settings,null)){require(((Number)inspector.attribute("queue."+queue,"messageCount")).longValue()==0,"Recovery wrote a new owner into an initialized empty replacement");}
        System.out.println("ARTEMIS_TRANSPORT_ACCEPTED: Java8 private SDK/current broker, no business creation on check, ownership, confirmation, non-destructive ACK, broker/client restart, unsafe queue refusal, lost-queue protection, native receipt verification, actual older same-ID nonempty backup refusal");
    }
}
